		['data2'] = 'p'
		},
	}


--[[--------------------------< S H O W F L A G >--------------------------------------------------------------

This function handles the |showflags= parameter from the template {{Infobox Chinese}}.  That template passes the
value to {{Infobox Chinese/Chinese}} which {{#invoke:}}s this module/function.  This function does not take any
frame parameters.  All parameter used by this function come from the {{Infobox Chinese/Chinese}} template parent
frame.

This function returns a child infobox or an empty string

{{#invoke:Module:Sandbox/trappist_the_monk/Ibox_zh|showflag}}

]]

local function showflag (frame)
	local pframe = frame:getParent();											-- there are no frame arguments for this function; all arguments must come from the parent (the template)
	local show_flag = pframe.args.showflag; 

	if (show_flag and '' == show_flag) or not show_flag then
		return '';																-- |showflag= not set so nothing to do; return empty string
	end

	local infobox_args = {};													-- table to hold arguments for frame:expandTemplate()

	infobox_args['child'] = 'yes';												-- showflag infoboen are always children
	infobox_args['labelstyle'] = 'font-weight:normal';							-- and always have this label style

	if transl_map[show_flag] then
		local i=1;
		while (1) do
			local label = 'label' .. i;											-- make label index that matches |labeln= parameter 
			local data = 'data' .. i;											-- make data index that matches |datan= parameter 
			if not transl_map[show_flag][label] then
				break;															-- not found then done
			end
			infobox_args[label] = label_map[transl_map[show_flag][label]];		-- add |labeln=<label text / wikilink>
			infobox_args[data] = pframe.args[transl_map[show_flag][data]];		-- add |datan={{{data}}}
			i = i + 1;															-- bump to next label / data pair
		end
	else
		return '';																-- |showflag= value invlaid; TODO: return error message?
	end

	return frame:expandTemplate ({title='Infobox', args = infobox_args});
	end


--[[--------------------------< T R A N S C R I P T I O N S >--------------------------------------------------

{{#invoke:Sandbox/trappist the monk/Ibox zh|transcriptions}}

]]

local function transcriptions (frame)
	local pframe = frame:getParent();											-- there are no frame arguments for this function; all arguments must come from the parent (the template)
	local show = 'no' == pframe.args.hide or nil;								-- make boolean-ish for controlling display of headers; |hide=no means show transcriptions without collapsed header

	local infobox_args = {};													-- table to hold arguments for frame:expandTemplate()
	local i;

	if show then
		infobox_args['subbox'] = 'yes';
		infobox_args['above'] = 'Transcriptions';
	else
		infobox_args['child'] = 'yes';
	end

	infobox_args['bodyclass'] = 'collapsible collapsed';
	infobox_args['abovestyle'] = 'font-size: 100%; text-align: left; background-color: #f9ffbc;';
	infobox_args['headerstyle'] = 'background-color: #dcffc9;';
	infobox_args['labelstyle'] = 'font-weight:normal;';

	i = 1;
	if pframe.args.p or pframe.args.bpmf or pframe.args.gr or pframe.args.w or pframe.args.tp or pframe.args.myr or pframe.args.mps or pframe.args.mi then
		infobox_args['header' .. i] = show and '[[Standard Chinese|Standard Mandarin]]';
		i = i + 1;
		for _, v in ipairs ({
			{'[[Hanyu Pinyin]]', 'p'},
			{'[[Bopomofo]]','bpmf'},
			{'[[Spelling in Gwoyeu Romatzyh|Gwoyeu Romatzyh]]', 'gr'},
			{'[[Wade–Giles]', 'w'},
			{'[[Tongyong Pinyin]]', 'tp'},
			{'[[Yale romanization of Mandarin|Yale Romanization]]', 'myr'},
			{'[[Mandarin Phonetic Symbols II|MPS2]]', 'mps'},
			{'[[Help:IPA/Mandarin|IPA]]', 'mi'}
			}) do
				infobox_args['label' .. i] = v[1];
				infobox_args['data' .. i] = pframe.args[v[2]];
				i = i + 1;
		end
	end

	i = 10;
	if pframe.args.xej or pframe.args['zh-dungan'] or pframe.args.sic then
		infobox_args['header' .. i] = show and '[[Mandarin Chinese|other Mandarin]]';
		i = i + 1;
		for _, v in ipairs ({
			{'[[Xiao\'erjing]]', 'xej'},
			{'[[Dungan language|Dungan]]','zh-dungan'},
			{'[[Sichuanese Mandarin|Sichuanese]] [[Sichuanese Pinyin|Pinyin]]', 'sic'},
			}) do
				infobox_args['label' .. i] = v[1];
				infobox_args['data' .. i] = pframe.args[v[2]];
				i = i + 1;
		end
	end

	i = 20;
	if pframe.args.wuu or pframe.args.lmz or pframe.args.ouji or pframe.args.suz then	-- ???? ouji was not included here in original template; whu?
		infobox_args['header' .. i] = show and '[[Wu Chinese|Wu]]';
		i = i + 1;
		for _, v in ipairs ({
			{'Romanization', 'wuu'},
			{'[[Shanghainese]]<br />Romanization','lmz'},
			{'[[Wenzhounese]]<br>  [[Wenzhounese romanisation|Romanisation]]', 'ouji'},
			{'[[Suzhounese]]', 'suz'},
			}) do
				infobox_args['label' .. i] = v[1];
				infobox_args['data' .. i] = pframe.args[v[2]];
				i = i + 1;
		end
	end

	i = 35;
	if pframe.args.gan then
		infobox_args['header' .. i] = show and '[[Gan Chinese|Gan]]';
		i = i + 1;
		for _, v in ipairs ({
			{'Romanization', 'gan'},
			}) do
				infobox_args['label' .. i] = v[1];
				infobox_args['data' .. i] = pframe.args[v[2]];
				i = i + 1;
		end
	end

  	i = 40;
	if pframe.args.hsn then
		infobox_args['header' .. i] = show and '[[Xiang Chinese|Xiang]]';
		i = i + 1;
		for _, v in ipairs ({
			{'IPA', 'hsn'},
			}) do
				infobox_args['label' .. i] = v[1];
				infobox_args['data' .. i] = pframe.args[v[2]];
				i = i + 1;
		end
	end

  	i = 45;
	if pframe.args.h or pframe.args.phfs then
		infobox_args['header' .. i] = show and '[[Hakka Chinese|Hakka]]';
		i = i + 1;
		for _, v in ipairs ({
			{'[[Guangdong Romanization#Hakka|Romanization]]', 'h'},
			{'[[Pha̍k-fa-sṳ]]', 'phfs'},
			}) do
				infobox_args['label' .. i] = v[1];
				infobox_args['data' .. i] = pframe.args[v[2]];
				i = i + 1;
		end
	end

  	i = 50;
	if pframe.args.y or pframe.args.ci or pframe.args.j or pframe.args.sl or pframe.args.gd or pframe.args.hk or pframe.args.mo then	-- ???? sl, hk, mo not here in original; why?
		infobox_args['header' .. i] = show and '[[Cantonese|Yue: Cantonese]]';
		i = i + 1;
		for _, v in ipairs ({
			{'[[Yale romanization of Cantonese|Yale Romanization]]', 'y'},
			{'[[Help:IPA/Cantonese|IPA]]', 'ci'},
			{'[[Jyutping]]', 'j'},
			{'[[Sidney Lau romanisation|Sidney Lau]]', 'sl'},
			{'[[Guangdong Romanization|Canton Romanization]]', 'gd'},
			{'[[Hong Kong Government Cantonese Romanisation|Hong Kong Romanisation]]', 'hk'},
			{'[[Cantonese#Romanization|Macau Romanization]]', 'mo'},
			}) do
				infobox_args['label' .. i] = v[1];
				infobox_args['data' .. i] = pframe.args[v[2]];
				i = i + 1;
		end
	end

  	i = 58;
	if pframe.args.toi then
		infobox_args['header' .. i] = show and '[[Yue Chinese|other Yue]]';
		i = i + 1;
		for _, v in ipairs ({
			{'[[Taishanese]]', 'toi'},
			}) do
				infobox_args['label' .. i] = v[1];
				infobox_args['data' .. i] = pframe.args[v[2]];
				i = i + 1;
		end
	end

	i = 60;
	if pframe.args.poj or pframe.args.tl or pframe.args.bp or pframe.args.teo or pframe.args.hain or pframe.args.lizu then	-- ???? bp not here in original; why?
		infobox_args['header' .. i] = show and '[[Southern Min]]';
		i = i + 1;
		for _, v in ipairs ({
			{'[[Hokkien]]', 'poj'},
			{'[[Taiwanese Romanization System|Tâi-lô]]', 'tl'},
			{'[[Bbánlám pìngyīm|Bbánlám Pìngyīm]]', 'bp'},
			{'[[Teochew dialect|Teochew]] [[Guangdong Romanization#Teochew|Peng\'im]]', 'teo'},
			{'[[Hainanese]] Romanization', 'hain'},
			{'[[Leizhou Min|Leizhou]] Romanization', 'lizu'},
			}) do
				infobox_args['label' .. i] = v[1];
				infobox_args['data' .. i] = pframe.args[v[2]];
				i = i + 1;
		end
	end

	i = 70;
	if pframe.args.buc then
		infobox_args['header' .. i] = show and '[[Eastern Min]]';
		i = i + 1;
		for _, v in ipairs ({
			{'[[Fuzhou dialect|Fuzhou]] [[Foochow Romanized|BUC]]', 'buc'},
			}) do
				infobox_args['label' .. i] = v[1];
				infobox_args['data' .. i] = pframe.args[v[2]];
				i = i + 1;
		end
	end

	i = 72;
	if pframe.args.hhbuc then
		infobox_args['header' .. i] = show and '[[Pu-Xian Min]]';
		i = i + 1;
		for _, v in ipairs ({
			{'[[Pu-Xian Min|Hinghwa]] [[Hinghwa Romanized|BUC]]', 'hhbuc'},
			}) do
				infobox_args['label' .. i] = v[1];
				infobox_args['data' .. i] = pframe.args[v[2]];
				i = i + 1;
		end
	end

	i = 74;
	if pframe.args.mblmc then
		infobox_args['header' .. i] = show and '[[Northern Min]]';
		i = i + 1;
		for _, v in ipairs ({
			{'[[Jian\'ou dialect|Jian\'ou]] [[Kienning Colloquial Romanized|Romanized]]', 'mblmc'},
			}) do
				infobox_args['label' .. i] = v[1];
				infobox_args['data' .. i] = pframe.args[v[2]];
				i = i + 1;
		end
	end

	i = 78;
	if pframe.args['phagspa-latin'] then
		infobox_args['header' .. i] = show and '[[Old Mandarin]]';
		i = i + 1;
		for _, v in ipairs ({
			{'Romanized \'Phags-pa', 'phagspa-latin'},
			}) do
				infobox_args['label' .. i] = v[1];
				infobox_args['data' .. i] = pframe.args[v[2]];
				i = i + 1;
		end
	end

	i = 81;
	if pframe.args.mc or pframe.args.emc or pframe.args.lmc then
		infobox_args['header' .. i] = show and '[[Middle Chinese]]';
		i = i + 1;
		for _, v in ipairs ({
			{'[[Middle Chinese]]', 'mc'},
			{'[[Middle Chinese#Early Middle Chinese|Early Middle Chinese]]', 'emc'},
			{'[[Middle Chinese#Late Middle Chinese|Late Middle Chinese]]', 'lmc'},
			}) do
				infobox_args['label' .. i] = v[1];
				infobox_args['data' .. i] = pframe.args[v[2]];
				i = i + 1;
		end
	end

	i = 91;
	if pframe.args['oc-b92'] or pframe.args['oc-bs'] or pframe.args['oc-zz'] then
		infobox_args['header' .. i] = show and '[[Old Chinese]]';
		i = i + 1;
		for _, v in ipairs ({
			{'[[Reconstructions_of_Old_Chinese#Baxter (1992)|Baxter (1992)]]', 'oc-b92'},
			{'[[Reconstructions of Old Chinese#Baxter–Sagart (2014)|Baxter–Sagart (2014)]]', 'oc-bs'},
			{'[[Reconstructions of Old Chinese#Zhengzhang (1981–1995)|Zhengzhang]]', 'oc-zz'},
			}) do
				infobox_args['label' .. i] = v[1];
				infobox_args['data' .. i] = pframe.args[v[2]];
				i = i + 1;
		end
	end

	return frame:expandTemplate ({title='Infobox', args = infobox_args});
	end


--[[--------------------------< E X P O R T E D   F U N C T I O N S >------------------------------------------
]]

return {
	showflag = showflag,
	transcriptions = transcriptions,
	}

--[[--------------------------< I S _ S E T >------------------------------------------------------------------

Returns true if argument is set; false otherwise. Argument is 'set' when it exists (not nil) or when it is not an empty string.

]]

local function is_set( var )
	return not (var == nil or var == '');
end


--[[--------------------------< A N Y _ S E T >----------------------------------------------------------------

Returns true if any member of the table is set; false otherwise. Argument is 'set' when it exists (not nil) or when it is not an empty string.

]]

local function any_set (t)
	for _, v in pairs (t) do
		if is_set (v) then
			return true;
		end
	end

	return false;
end


