--[[--------------------------< T R A N S C R I P T I O N >----------------------------------------------------

]]

local function transcription (infobox_args, pframe, idx, show, i)
	infobox_args['header' .. i] = show and xscript[idx].header;
	i = i + 1;
	for _, v in ipairs (xscript[idx].t) do
		infobox_args['label' .. i] = v[1];
		infobox_args['data' .. i] = pframe.args[v[2]];
		i = i + 1;
	end
	return i;
end


--[[--------------------------< T R A N S C R I P T I O N S >--------------------------------------------------

Module entry point

This function handles the transcription infobox called by {{Infobox Chinese/Chinese}}.

{{#invoke:Sandbox/trappist the monk/Ibox zh|transcriptions}}

]]

local function transcriptions (frame)
	local pframe = frame:getParent();											-- there are no frame arguments for this function; all arguments must come from the parent (the template)
	local show = 'no' ~= pframe.args.hide or nil;								-- make boolean-ish for controlling display of headers; |hide=no means show transcriptions without collapsed header

	local infobox_args = {};													-- table to hold arguments for frame:expandTemplate()
	local i;

	if show then
		infobox_args['subbox'] = 'yes';
		infobox_args['above'] = 'Transcriptions';
	else
		infobox_args['child'] = 'yes';
	end

	infobox_args['bodyclass'] = 'collapsible collapsed';
	infobox_args['abovestyle'] = 'font-size: 100%; text-align: left; background-color: #f9ffbc;';
	infobox_args['headerstyle'] = 'background-color: #dcffc9;';
	infobox_args['labelstyle'] = 'font-weight:normal;';

	i = 1;
	if any_set ({pframe.args.p, pframe.args.bpmf, pframe.args.gr, pframe.args.w, pframe.args.tp, pframe.args.myr, pframe.args.mps, pframe.args.mi}) then
		i = transcription (infobox_args, pframe, 'standard mandarin', show, i);
	end

--	i = 10;
	if any_set ({pframe.args.xej, pframe.args['zh-dungan'], pframe.args.sic}) then
		i = transcription (infobox_args, pframe, 'other mandarin', show, i);
	end

--	i = 20;
	if any_set ({pframe.args.wuu, pframe.args.lmz, pframe.args.ouji, pframe.args.suz}) then	-- ???? ouji was not included here in original template; whu?
		i = transcription (infobox_args, pframe, 'wu', show, i);
	end

--	i = 35;
	if is_set (pframe.args.gan) then
		i = transcription (infobox_args, pframe, 'gan', show, i);
	end

--	i = 40;
	if is_set (pframe.args.hsn) then
		i = transcription (infobox_args, pframe, 'xiang', show, i);
	end

--  	i = 45;	
	if any_set ({pframe.args.h, pframe.args.phfs}) then
		i = transcription (infobox_args, pframe, 'hakka', show, i);
	end

--  	i = 50;
	if any_set ({pframe.args.y, pframe.args.ci, pframe.args.j, pframe.args.sl, pframe.args.gd, pframe.args.hk, pframe.args.mo}) then	-- ???? sl, hk, mo not here in original; why?
		i = transcription (infobox_args, pframe, 'yue cantonese', show, i);
	end

--  	i = 58;
	if is_set (pframe.args.toi) then
		i = transcription (infobox_args, pframe, 'other yue', show, i);
	end

--	i = 60;
	if any_set ({pframe.args.poj, pframe.args.tl, pframe.args.bp, pframe.args.teo, pframe.args.hain, pframe.args.lizu}) then	-- ???? bp not here in original; why?
		i = transcription (infobox_args, pframe, 'southern min', show, i);
	end

--	i = 70;
	if is_set (pframe.args.buc) then
		i = transcription (infobox_args, pframe, 'eastern min', show, i);
	end

--	i = 72;
	if is_set (pframe.args.hhbuc) then
		i = transcription (infobox_args, pframe, 'pu-xian min', show, i);
	end

--	i = 74;
	if is_set (pframe.args.mblmc) then
		i = transcription (infobox_args, pframe, 'northern min', show, i);
	end

--	i = 78;
	if is_set (pframe.args['phagspa-latin']) then
		i = transcription (infobox_args, pframe, 'old mandarin', show, i);
	end

--	i = 81;
	if any_set ({pframe.args.mc, pframe.args.emc, pframe.args.lmc}) then
		i = transcription (infobox_args, pframe, 'middle chinese', show, i);
	end

--	i = 91;
	if any_set ({pframe.args['oc-b92'], pframe.args['oc-bs'], pframe.args['oc-zz']}) then
		i = transcription (infobox_args, pframe, 'old chinese', show, i);
	end

	return frame:expandTemplate ({title='Infobox', args = infobox_args});
	end


