--[[--------------------------< T R A N S C R I P T I O N >----------------------------------------------------

This function does that repetative work when assembling the parameter list for {{Infobox}} template

inputs are:
	infobox_args - table of infobox parameters
	args - args table from parent frame (the template paramters)
	idx - index into xscript table
	show - pseudo-boolean (true or nil) header display flag; when true display the header
	i - enumerator for {{infobox}} parameters |headern=, |labeln=, |datan=; in this application i continually
		increments; there are no gaps as there are in the original template

returns i for the next time this function is called

]]

local function transcription (infobox_args, args, idx, show, i)
	infobox_args['header' .. i] = show and xscript[idx].header;					-- if headers are displayed
	i = i + 1;																	-- bump the enumerator
	for _, v in ipairs (xscript[idx].t) do										-- each label / data pair in the xscript subtable
		infobox_args['label' .. i] = v[1];										-- make an enumerated label parameter
		infobox_args['data' .. i] = args[v[2]];									-- make an enumerated data parameter
		i = i + 1;																-- bump the enumerator
	end

	return i;																	-- and done
end


--[[--------------------------< T R A N S C R I P T I O N S >--------------------------------------------------

Module entry point

This function handles the transcription infobox called by {{Infobox Chinese/Chinese}}.  Creates header and label / data
pairs according to the presence of certain parameters provided to {{Infobox Chinese}}

{{#invoke:Sandbox/trappist the monk/Ibox zh|transcriptions}}

]]

local function transcriptions (frame)
	local args = frame:getParent().args;										-- there are no frame arguments for this function; all arguments must come from the parent (the template)
	local show = 'no' ~= args.hide or nil;										-- make boolean-ish for controlling display of headers; |hide=no means show transcriptions without collapsed header

	local infobox_args = {};													-- table to hold arguments for frame:expandTemplate()
	local i = 1;																-- enumerator used with {{infobox}} |headern=, |labeln=, and |datan= parameters

	if show then
		infobox_args['subbox'] = 'yes';
		infobox_args['above'] = 'Transcriptions';
	else
		infobox_args['child'] = 'yes';
	end

	infobox_args['bodyclass'] = 'collapsible collapsed';
	infobox_args['abovestyle'] = 'font-size: 100%; text-align: left; background-color: #f9ffbc;';
	infobox_args['headerstyle'] = 'background-color: #dcffc9;';
	infobox_args['labelstyle'] = 'font-weight:normal;';
																				-- 
	if any_set ({args.p, args.bpmf, args.gr, args.w, args.tp, args.myr, args.mps, args.mi}) then
		i = transcription (infobox_args, args, 'standard mandarin', show, i);
	end

--	10; header enumerator used in original template; not likely to be the same enumerator here
	if any_set ({args.xej, args['zh-dungan'], args.sic}) then
		i = transcription (infobox_args, args, 'other mandarin', show, i);
	end

--	20;
	if any_set ({args.wuu, args.lmz, args.ouji, args.suz}) then					-- ???? ouji was not included here in original template; whu?
		i = transcription (infobox_args, args, 'wu', show, i);
	end

--	35;
	if is_set (args.gan) then
		i = transcription (infobox_args, args, 'gan', show, i);
	end

--	40;
	if is_set (args.hsn) then
		i = transcription (infobox_args, args, 'xiang', show, i);
	end

--	45;	
	if any_set ({args.h, args.phfs}) then
		i = transcription (infobox_args, args, 'hakka', show, i);
	end

--	50;
	if any_set ({args.y, args.ci, args.j, args.sl, args.gd, args.hk, args.mo}) then	-- ???? sl, hk, mo not here in original; why?
		i = transcription (infobox_args, args, 'yue cantonese', show, i);
	end

--	58;
	if is_set (args.toi) then
		i = transcription (infobox_args, args, 'other yue', show, i);
	end

--	60;
	if any_set ({args.poj, args.tl, args.bp, args.teo, args.hain, args.lizu}) then	-- ???? bp not here in original; why?
		i = transcription (infobox_args, args, 'southern min', show, i);
	end

--	70;
	if is_set (args.buc) then
		i = transcription (infobox_args, args, 'eastern min', show, i);
	end

--	72;
	if is_set (args.hhbuc) then
		i = transcription (infobox_args, args, 'pu-xian min', show, i);
	end

--	74;
	if is_set (args.mblmc) then
		i = transcription (infobox_args, args, 'northern min', show, i);
	end

--	78;
	if is_set (args['phagspa-latin']) then
		i = transcription (infobox_args, args, 'old mandarin', show, i);
	end

--	81;
	if any_set ({args.mc, args.emc, args.lmc}) then
		i = transcription (infobox_args, args, 'middle chinese', show, i);
	end

--	91;
	if any_set ({args['oc-b92'], args['oc-bs'], args['oc-zz']}) then
		i = transcription (infobox_args, args, 'old chinese', show, i);
	end

	return frame:expandTemplate ({title='Infobox', args = infobox_args});		-- render the infobox and done
	end


--[[-------------------------< I B O X _ Z H _ Z H >----------------------------------------------------------

implements {{Infobox Chinese/Chinese}}

Module entry point

{{#invoke:Sandbox/trappist_the_monk/Ibox_zh|ibox_zh_zh}}

]]

local function ibox_zh_zh (frame)
	local args = frame:getParent().args;										-- there are no frame arguments for this function; all arguments must come from the parent (the template)
	local infobox_args = {};													-- table to hold arguments for frame:expandTemplate()

	infobox_args['child'] = 'yes';
	infobox_args['headerstyle'] = 'background-color: ' .. is_set (args.headercolor) and args.headercolor or '#b0c4de' .. ';';
	infobox_args['labelstyle'] = 'font-weight:normal;';

	if 'none' ~= args.header and 'none' ~= args.chinese_header then
		infobox_args['header1'] = args.header or args.chinese_header or 'Chinese name';
	end

	infobox_args['label2'] = '[[Chinese language|Chinese]]';
	if is_set (args.c) then
		infobox_args['data2'] = frame:expandTemplate ({title='Lang', args = {'zh-Hani', args.c, size = '1rem'}});
	end

	if 'st' == args.order then
		infobox_args['label3'] = '[[Simplified Chinese characters|Simplified Chinese]]';
		if is_set (args.s) then
			infobox_args['data3'] = frame:expandTemplate ({title='Lang', args = {'zh-Hans', args.s, size = '1rem'}});
		end

		infobox_args['label4'] = '[[Traditional Chinese characters|Traditional&nbsp;Chinese]]';
		if is_set (args.t) then
			infobox_args['data4'] = frame:expandTemplate ({title='Lang', args = {'zh-Hant', args.t, size = '1rem'}});
		end
	else
		infobox_args['label3'] = '[[Traditional Chinese characters|Traditional&nbsp;Chinese]]';
		if is_set (args.t) then
			infobox_args['data3'] = frame:expandTemplate ({title='Lang', args = {'zh-Hant', args.t, size = '1rem'}});
		end

		infobox_args['label4'] = '[[Simplified Chinese characters|Simplified Chinese]]';
		if is_set (args.s) then
			infobox_args['data4'] = frame:expandTemplate ({title='Lang', args = {'zh-Hans', args.s, size = '1rem'}});
		end
	end

	infobox_args['label5'] = '[[\'Phags-pa script]]';							-- ???? this parameter isn't passed from {{Infobox Chinese}} to {{infobox Chinese/Chinese}}
	if is_set (args.phagspa) then
		infobox_args['data5'] = frame:expandTemplate ({title='Phagspa', args = {'h', args.phagspa, args['phagspa-latin'], size = 12}});
	end

	infobox_args['data6'] = showflag (frame);									-- needs frame so that it can frame:expandTemplate()

	infobox_args['label7'] = '[[Chinese postal romanization|Postal]]';
	infobox_args['data7'] = is_set (args.psp) and args.psp or nil;

	infobox_args['label8'] = 'Literal meaning';
	infobox_args['data8'] = is_set (args.l) and args.l or nil;

	if 'no' == args.hide then
		infobox_args['rowstyle9'] = 'display:none;';
		infobox_args['rowcellstyle9'] = 'display:none;';
	end

	if any_set ({args.c, args.t, args.p, args.s, args.phagspa}) then			-- ???? phagspa not passed into {{infobox Chinese/Chinese}}  Why?
		infobox_args['data8'] = transcriptions (frame);							-- needs frame so that it can frame:expandTemplate()
	end

	return frame:expandTemplate ({title='Infobox', args = infobox_args});
	end


--[[--------------------------< E X P O R T E D   F U N C T I O N S >------------------------------------------
]]

return {
	showflag = showflag,
	transcriptions = transcriptions,
	}

--[[--------------------------< I S _ S E T >------------------------------------------------------------------

Returns true if argument is set; false otherwise. Argument is 'set' when it exists (not nil) or when it is not an empty string.

]]

local function is_set( var )
	return not (var == nil or var == '');
end


--[[--------------------------< A N Y _ S E T >----------------------------------------------------------------

Returns true if any member of the table is set; false otherwise. Argument is 'set' when it exists (not nil) or when it is not an empty string.

]]

local function any_set (t)
	for _, v in pairs (t) do
		if is_set (v) then
			return true;
		end
	end

	return false;
end


