--[[-------------------------< I B O X _ Z H _ Z H >----------------------------------------------------------

implements {{Infobox Chinese/Chinese}}

Module entry point

{{#invoke:Sandbox/trappist_the_monk/Ibox_zh|ibox_zh_zh}}

]]

local function ibox_zh_zh (frame)
	local args = frame:getParent().args;										-- there are no frame arguments for this function; all arguments must come from the parent (the template)
	local infobox_args = {};													-- table to hold arguments for frame:expandTemplate()

	infobox_args['child'] = 'yes';
	local h_color;
	if is_set (args.headercolor) then
		h_color = args.headercolor;
	else
		h_color = '#b0c4de'
	end

	infobox_args['headerstyle'] = 'background-color: ' ..  h_color .. ';';
	infobox_args['labelstyle'] = 'font-weight:normal;';

	if 'none' ~= args.header and 'none' ~= args.chinese_header then
		infobox_args['header1'] = args.header or args.chinese_header or 'Chinese name';
	end

	infobox_args['label2'] = '[[Chinese language|Chinese]]';
	if is_set (args.c) then
		infobox_args['data2'] = frame:expandTemplate ({title='Lang', args = {'zh-Hani', args.c, size = '1rem'}});
	end

	if 'st' == args.order then
		infobox_args['label3'] = '[[Simplified Chinese characters|Simplified Chinese]]';
		if is_set (args.s) then
			infobox_args['data3'] = frame:expandTemplate ({title='Lang', args = {'zh-Hans', args.s, size = '1rem'}});
		end

		infobox_args['label4'] = '[[Traditional Chinese characters|Traditional&nbsp;Chinese]]';
		if is_set (args.t) then
			infobox_args['data4'] = frame:expandTemplate ({title='Lang', args = {'zh-Hant', args.t, size = '1rem'}});
		end
	else
		infobox_args['label3'] = '[[Traditional Chinese characters|Traditional&nbsp;Chinese]]';
		if is_set (args.t) then
			infobox_args['data3'] = frame:expandTemplate ({title='Lang', args = {'zh-Hant', args.t, size = '1rem'}});
		end

		infobox_args['label4'] = '[[Simplified Chinese characters|Simplified Chinese]]';
		if is_set (args.s) then
			infobox_args['data4'] = frame:expandTemplate ({title='Lang', args = {'zh-Hans', args.s, size = '1rem'}});
		end
	end

	infobox_args['label5'] = '[[\'Phags-pa script]]';							-- ???? this parameter isn't passed from {{Infobox Chinese}} to {{infobox Chinese/Chinese}}
	if is_set (args.phagspa) then
		infobox_args['data5'] = frame:expandTemplate ({title='Phagspa', args = {'h', args.phagspa, args['phagspa-latin'], size = 12}});
	end

	infobox_args['data6'] = showflag (frame);									-- needs frame so that it can frame:expandTemplate()

	infobox_args['label7'] = '[[Chinese postal romanization|Postal]]';
	infobox_args['data7'] = is_set (args.psp) and args.psp or nil;

	infobox_args['label8'] = 'Literal meaning';
	infobox_args['data8'] = is_set (args.l) and args.l or nil;

	if 'no' == args.hide then
		infobox_args['rowstyle9'] = 'display:none;';
		infobox_args['rowcellstyle9'] = 'display:none;';
	end

	if any_set ({args.c, args.t, args.p, args.s, args.phagspa}) then			-- ???? phagspa not passed into {{infobox Chinese/Chinese}}  Why?
		infobox_args['data8'] = transcriptions (frame);							-- needs frame so that it can frame:expandTemplate()
	end

	return frame:expandTemplate ({title='Infobox', args = infobox_args});
	end


--[[--------------------------< E X P O R T E D   F U N C T I O N S >------------------------------------------
]]

return {
	ibox_zh_zh = ibox_zh_zh,
	showflag = showflag,
	transcriptions = transcriptions,
	}

--[[--------------------------< I S _ S E T >------------------------------------------------------------------

Returns true if argument is set; false otherwise. Argument is 'set' when it exists (not nil) or when it is not an empty string.

]]

local function is_set( var )
	return not (var == nil or var == '');
end


--[[--------------------------< A N Y _ S E T >----------------------------------------------------------------

Returns true if any member of the table is set; false otherwise. Argument is 'set' when it exists (not nil) or when it is not an empty string.

]]

local function any_set (t)
	for _, v in pairs (t) do
		if is_set (v) then
			return true;
		end
	end

	return false;
end


