	if any_set ({args.mr, args.rr}) then
		infobox_args['data5'] = transcriptions (frame, 'ko');					-- needs frame so that it can frame:expandTemplate()
	end

	if show then
		if is_set (args.rr) then
			infobox_args['label6'] = '[[Revised Romanization of Korean|Revised Romanization]]';
			infobox_args['data6'] = frame:expandTemplate ({title='transl', args = {'ko', 'rr', args.rr}});
		end
		if is_set (args.mr) then
			infobox_args['label7'] = '[[McCune–Reischauer]]';
