	end

	if any_set ({args.mr, args.rr}) then
		infobox_args['data5'] = transcriptions (frame, 'ko');					-- needs frame so that it can frame:expandTemplate()
	end

	if show then
		if is_set (args.rr) then
			infobox_args['label6'] = '[[Revised Romanization of Korean|Revised Romanization]]';
			infobox_args['data6'] = frame:expandTemplate ({title='transl', args = {'ko', 'rr', args.rr}});
		end
		if is_set (args.mr) then
			infobox_args['label7'] = '[[McCune–Reischauer]]';
			infobox_args['data7'] = frame:expandTemplate ({title='transl', args = {'ko', 'mr', args.mr}});
		end
		if is_set (args.koreanipa) then
			infobox_args['label8'] = '[[Help:IPA/Korean|IPA]]';
			infobox_args['data8'] = args.koreanipa;
		end
	end

	return frame:expandTemplate ({title='Infobox', args = infobox_args});
end


--[[--------------------------< E X P O R T E D   F U N C T I O N S >------------------------------------------
]]

return {
	ibox_zh_ko = ibox_zh_ko,													-- {{infobox Chinese/Korean}}
	ibox_zh_zh = ibox_zh_zh,													-- {{infobox Chinese/Chinese}}
	}

--[[--------------------------< I S _ S E T >------------------------------------------------------------------

Returns true if argument is set; false otherwise. Argument is 'set' when it exists (not nil) or when it is not an empty string.

]]

local function is_set( var )
	return not (var == nil or var == '');
end


--[[--------------------------< A N Y _ S E T >----------------------------------------------------------------

Returns true if any member of the table is set; false otherwise. Argument is 'set' when it exists (not nil) or when it is not an empty string.

]]

local function any_set (t)
	for _, v in pairs (t) do
		if is_set (v) then
			return true;
		end
	end

	return false;
end


