local function ibox_zh_ko (frame)
	local args = frame:getParent().args;										-- there are no frame arguments for this function; all arguments must come from the parent (the template)
	local show = 'no' ~= args.hide or nil;										-- make boolean-ish for controlling display of headers; |hide=no means show transcriptions without collapsed header
	local infobox_args = {};													-- table to hold arguments for frame:expandTemplate()

	infobox_args['child'] = 'yes';
	local h_color;
	if is_set (args.headercolor) then
		h_color = args.headercolor;
	else
		h_color = '#b0c4de'
	end

	infobox_args['headerstyle'] = 'background-color: ' ..  h_color .. ';';

	if is_set (args.fontstyle) then												-- ???? |fontstyle= is not a documented parameter; why is it used here?
		infobox_args['labelstyle'] = 'font-weight:' .. fontstyle .. ';';
	else
		infobox_args['labelstyle'] = 'font-weight:normal;';
	end

	if 'none' ~= args.header and 'none' ~= args.korean_header then
		infobox_args['header1'] = args.header or args.korean_header or 'Korean name';
	end

	local i = 2;

	if 'yes' == args.northkorea then
		infobox_args['label2'] = '[[Hangul|Chosŏn\'gŭl]]';
	elseif 'old' == args.northkorea then
		infobox_args['label2'] = '[[Hunminjeongeum]]';
	else
		infobox_args['label2'] = '[[Hangul]]';
	end

	if is_set (args.hangul) then
		infobox_args['data2'] = frame:expandTemplate ({title='Lang', args = {'ko-Hang', args.hangul, size = '1rem'}});
	end

	if 'yes' == args.northkorea then
		infobox_args['label3'] = '[[Hanja|Hancha]]';
	else
		infobox_args['label3'] = '[[Hanja]]';
	end

	if is_set (args.hanja) then
		infobox_args['data3'] = frame:expandTemplate ({title='Lang', args = {'ko-Hani', args.hanja, size = '1rem'}});
	end

	if is_set (args.lk) then
		infobox_args['label4'] = 'Literal meaning';
		infobox_args['data4'] = args.lk;
	end

	if show then
		if any_set ({args.mr, args.rr}) then
			infobox_args['data5'] = transcriptions (frame, 'ko');				-- needs frame so that it can frame:expandTemplate()
		end
	else
		if is_set (args.rr) then
			infobox_args['label6'] = '[[Revised Romanization of Korean|Revised Romanization]]';
			infobox_args['data6'] = frame:expandTemplate ({title='transl', args = {'ko', 'rr', args.rr}});
		end
		if is_set (args.mr) then
			infobox_args['label7'] = '[[McCune–Reischauer]]';
			infobox_args['data7'] = frame:expandTemplate ({title='transl', args = {'ko', 'mr', args.mr}});
		end
		if is_set (args.koreanipa) then
			infobox_args['label8'] = '[[Help:IPA/Korean|IPA]]';
			infobox_args['data8'] = args.koreanipa;
		end
	end

	return frame:expandTemplate ({title='Infobox', args = infobox_args});
end


