|image2       = {{#invoke:InfoboxImage|InfoboxImage|image={{{pic2<includeonly>|</includeonly>}}}|sizedefault=frameless|size={{{picsize2<includeonly>|</includeonly>}}}|upright={{{picupright2|}}}|alt={{{picalt2<includeonly>|</includeonly>}}}{{{pictooltip2<includeonly>|</includeonly>}}} }}
]]

	infobox_args['headerstyle'] = 'background-color:' .. h_color;
